import React from 'react';
import { Meta, Story } from '@storybook/react';
import Toggle from './Toggle';

export default {
  title: 'Data Entry/Toggle',
  component: Toggle,
  argTypes: {
    disabled: {
      table: {
        type: {
          summary: 'boolean',
        },
      },
      control: {
        type: 'boolean',
      },
      description: 'Disabled state for the toggle component',
    },
    defaultChecked: {
      table: {
        type: {
          summary: 'boolean',
        },
      },
      control: {
        type: 'boolean',
      },
      description:
        'Default value for the toggle component. Use when you do not need to control its state',
    },
    checked: {
      table: {
        type: {
          summary: 'boolean',
        },
      },
      control: {
        type: 'boolean',
      },
      description:
        'Value to be passed when toggle component is controlled. Must be used in conjunction with `onCheckedChange`',
    },
    onCheckedChange: {
      table: {
        type: {
          summary: '(checked: boolean) => void',
        },
      },
      description: 'Callback function triggered when the state of the toggle changes',
    },
    name: {
      table: {
        type: {
          summary: 'string',
        },
      },
      description:
        'The name of the toggle. Submitted with its owning form as part of a name/value pair',
    },
    value: {
      table: {
        type: {
          summary: 'string',
        },
        defaultValue: {
          summary: 'on',
        },
      },
      description: 'The value given as data when submitted with a name',
    },
  },
  parameters: {
    docs: {
      description: {
        component:
          'The `Toggle` component was created using `Switch` from Radix. So it accepts all props from Root, except `asChild`.<br><br>How to install: `yarn add @hexa-ui/components`<br><br>How to import: `import { Toggle } from "@hexa-ui/components"`',
      },
    },
  },
} as Meta;

const Template: Story = (args) => <Toggle {...args} />;

export const uncontrolled = Template.bind({});

export const disabled = Template.bind({});
disabled.args = {
  disabled: true,
};

export const Controlled = (): JSX.Element => {
  const [checked, setChecked] = React.useState(false);
  const ref = React.useRef<HTMLButtonElement>(null);

  const onChange = (value: boolean) => {
    setChecked(value);
    alert('Triggered onChange Function');
  };

  return (
    <>
      <button
        style={{ margin: '10px 0' }}
        type="button"
        onClick={() => setChecked((prev) => !prev)}
      >
        Toggle value
      </button>
      <Toggle checked={checked} onCheckedChange={onChange} ref={ref} />
    </>
  );
};
